"""Verify the fresh-map demo generated by the normal story builder."""
import bpy
import sys
from pathlib import Path
root=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(root/"blender/scripts"))
from story_config import read_story, shared_trace_intervals

config=read_story(root/"examples/fresh-maple.json")
assert config["style_preset"]=="maple"
assert not config["editorial_text"]
assert shared_trace_intervals([[100],[200]],60,15)==[[(0,60)],[(15,135)]]
rail=config["layers"][0]
by_id={f["properties"]["id"]:f["geometry"]["coordinates"] for f in rail["features"]}
assert set(by_id)=={"GREEN","ORANGE","RED","BLUE","SILVER","TRE"}
north=[tuple(p) for p in by_id["RED"] if -96.80<p[0]<-96.77 and 32.79<p[1]<32.83]
assert len(north)>60 and set(north)<=set(map(tuple,by_id["ORANGE"])) and set(north)<=set(map(tuple,by_id["BLUE"]))
scene=bpy.context.scene
scene.frame_set(90)
objects=scene.collection.children["DART rail"].objects
for key in by_id:
    assert key in objects
    assert objects[key].data.shape_keys is not None
    opacity=next(n for n in objects[key].data.materials[0].node_tree.nodes if n.label=="Layer opacity")
    assert abs(opacity.inputs[0].default_value-rail["route_overrides"][key].get("opacity",1))<.01
assert any("Hospital silhouette" in o.name for o in scene.objects)
assert any("Hospital details" in o.name for o in scene.objects)
assert {o.name for o in scene.collection.children["Screen titles"].objects}=={"Screen coordinates","Map sources"}
print("Verified packaged DART rail, shared north alignment, preset opacity, hospital and editorial default")
